<?php use app\services\Ui;use app\services\Catalog;use yii\helpers\Html;$this->title='Hisoblash qoidalari';$v=fn($key,$default='')=>Yii::$app->request->post($key,$edit[$key]??$default);$types=['BirlikUchun'=>'Har bir natija uchun','QatiyBall'=>'Bir martalik ball','ChegaraliYigindi'=>'Maksimal limitli yig‘indi','Ballgacha'=>'Ekspert bahosi','DarajaShkalasi'=>'Sifat shkalasi','PulFormulasi'=>'Grant summasi formulasi','XirshIndeksi'=>'Xirsh indeksi']; ?>
<div class="page-heading"><div><span class="eyebrow">NORMATIV SOZLAMALAR</span><h1>Hisoblash qoidalari</h1><p>Ochiq qolgan mezon talqinini qaror asosi bilan belgilang.</p></div></div><section class="card"><?= Html::beginForm(['admin/rules'],'get',['class'=>'filters']) ?><?= Ui::select('Davr','period',$periodId,[''=>'Davrni tanlang']+array_column($periods,'name','id')) ?><?= Ui::select('Toifa','category',$category,Catalog::CATEGORIES) ?><?= Ui::input('Ko‘rsatkich qidiruvi','q',Yii::$app->request->get('q',''),'search') ?><button class="button secondary">Ko‘rsatish</button><?= Html::endForm() ?><div class="alert warning">96 ta manba ko‘rsatkichida talqin savollari bor. Ularni qaror asosisiz ochmang. Grant uchun 100 MHTEKM summasi va yaxlitlash usulini; Xirsh uchun to‘liq indeks yoki yillik o‘sish olinishi haqidagi qarorni belgilang.</div></section>
<?php if($edit): ?><section class="card"><h2><?= Ui::h($edit['name']) ?></h2><blockquote><?= Ui::h($edit['source_text']) ?></blockquote><p class="muted"><?= Ui::h($edit['source_note']) ?></p><?= Html::beginForm(['admin/rules','period'=>$periodId,'category'=>$category,'id'=>$edit['id']],'post') ?><div class="two-columns"><?= Ui::select('Hisoblash turi','calc_type',$v('calc_type'),$types) ?><?= Ui::input('Birlik balli','base_score',$v('base_score'),'number',['min'=>0,'step'=>'.01']) ?><?= Ui::input('Ekspert bahosi chegarasi','upper_score',$v('upper_score'),'number',['min'=>0,'step'=>'.01']) ?><?= Ui::input('Davr bo‘yicha maksimal jami (ixtiyoriy)','cap_score',$v('cap_score'),'number',['min'=>0,'step'=>'.01']) ?></div><div class="checks"><label class="check"><?= Html::checkbox('enabled',(bool)$v('enabled',0)) ?> Qoida tasdiqlangan, arizaga ochiq</label><label class="check"><?= Html::checkbox('once_only',(bool)$v('once_only',0)) ?> Davrda bir martalik</label></div><?= Ui::input('100 MHTEKM summasi (faqat grant uchun, so‘m)','formula_divisor',$v('formula_divisor'),'number',['min'=>'.01','step'=>'.01']) ?><?= Ui::select('Grant hisoblash usuli','formula_mode',$v('formula_mode'),[''=>'Tanlang','proportional'=>'Proporsional','floor'=>'Faqat to‘liq 100 MHTEKM bloklari']) ?><?= Ui::input('O‘zaro istisno guruh kodi (ixtiyoriy, masalan: phd_til)','exclusive_group',$v('exclusive_group'),'text',['maxlength'=>80]) ?><p class="muted">Bir guruhga tegishli ko‘rsatkichlardan davrda bittasi tasdiqlanadi. Masalan, B1/B2 yoki sifat darajalarini shu yo‘l bilan cheklashingiz mumkin.</p><?= Ui::area('Qaror asosi / buyruq / qo‘llanish shartlari','decision',$v('decision'),['required'=>true,'minlength'=>10,'maxlength'=>3000]) ?><button class="button">Qoidani saqlash</button><?= Html::endForm() ?></section><?php endif ?>
<section class="card"><h2>Davr ko‘rsatkichlari</h2><?php if(!$rows): ?><?= Ui::empty('Davr va toifani tanlang.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Ko‘rsatkich</th><th>Turi</th><th>Ball</th><th>Holat</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><b><?= Ui::h($row['name']) ?></b><small><?= Ui::h($row['code']) ?></small></td><td><?= Ui::h($types[$row['calc_type']]??$row['calc_type']) ?></td><td><?= Ui::h($row['base_score']??$row['upper_score']??'—') ?></td><td><span class="badge <?= $row['enabled']?'approved':'returned' ?>"><?= $row['enabled']?'Ochiq':'Qaror kerak' ?></span></td><td><?= Html::a('Sozlash',['admin/rules','period'=>$periodId,'category'=>$category,'id'=>$row['id']],['class'=>'text-link']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
